def count_nums(arr):
    """
    Count the number of elements in the array which has a sum of digits > 0.

    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.

    Args:
        arr (list): A list of integers.

    Returns:
        int: The number of elements with a sum of digits > 0.
    """
    def sum_of_digits(n):
        """Return the sum of the signed digits of a number."""
        if n < 0:
            return -1 * (abs(n) // 10 ** len(str(abs(n)) - 1)) + sum_of_digits(n // 10 ** (len(str(abs(n)) - 1)))
        else:
            return sum(int(digit) for digit in str(n))

    return sum(1 for num in arr if sum_of_digits(num) > 0)
