def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


def intersection(interval1, interval2):
    """Return 'YES' if the length of the intersection of two intervals is a prime number, 'NO' otherwise."""
    # Find the intersection of two intervals
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])

    # Check if the intervals intersect
    if start > end:
        return "NO"

    # Calculate the length of the intersection
    intersection_length = end - start + 1

    # Check if the length of the intersection is a prime number
    if is_prime(intersection_length):
        return "YES"
    else:
        return "NO"


# Test cases
print(intersection((1, 2), (2, 3)))  # ==> "NO"
print(intersection((-1, 1), (0, 4)))  # ==> "NO"
print(intersection((-3, -1), (-5, 5)))  # ==> "YES"
```

This function `intersection(interval1, interval2)` takes two intervals as input and returns a string indicating whether the length of their intersection is a prime number or not. It first checks if the intervals intersect, then calculates the length of the intersection, and finally checks if the length is prime using the `is_prime(n)` function. The `is_prime(n)` function uses a simple trial division method to check if a number is prime.
